#!/bin/bash
set -e

echo "=== Exporting PJSIP Recipe ==="
.venv/bin/conan export conan/pjsip --version=2.14.1

echo "=== Installing Dependencies with Conan ==="
# This will build PJSIP and other dependencies if missing
.venv/bin/conan install . --build=missing -c "tools.cmake.cmaketoolchain:extra_variables={'SDL_PIPEWIRE': 'OFF', 'SDL_WAYLAND': 'OFF'}"

echo "=== Configuring CMake ==="
# Use the preset generated by Conan
cmake --preset conan-release -DCMAKE_EXPORT_COMPILE_COMMANDS=ON

echo "=== Building Project ==="
cmake --build --preset conan-release -j$(nproc)

# Link compile_commands.json for IDE support
ln -sf build/compile_commands.json .

echo "=== Build Complete ==="
echo "Run using: ./build/microsip_clone"
